use std::collections::HashMap;

fn two_sum(nums: &Vec<i32>, target: i32) -> Vec<usize> {
    // Map from value -> its earliest index seen so far.
    let mut seen: HashMap<i32, usize> = HashMap::with_capacity(nums.len());

    for (i, &x) in nums.iter().enumerate() {
        let need = target - x;
        if let Some(&j) = seen.get(&need) {
            // j < i because j was inserted earlier.
            return vec![j, i];
        }
        // Keep the earliest index for each value (doesn't matter under uniqueness,
        // but it preserves increasing-order return for the first valid pair).
        seen.entry(x).or_insert(i);
    }

    // By problem guarantee, exactly one solution exists.
    unreachable!("no two-sum solution found despite guarantee");
}